Definition rsimeq {A} (R : rel) (m1 : M S1 A) (m2 : M S2 A) (Q : A -> rel) : Prop :=
  rsim R m1 m2 (fun a b s1 mo1 s2 mo2 => a = b /\ Q a s1 mo1 s2 mo2).

