Section Target.
Context {P1 P2 : Type}.
(* [comment removed for export] *)
Variable RX : list (P1 * P2 * Z) -> Z -> rel.
Variables (malloc1 : Z -> M S1 (option P1)) (malloc2 : Z -> M S2 (option P2)).
Variables (free1 : P1 -> M S1 unit) (free2 : P2 -> M S2 unit).
Variables (nh1 : M S1 Empty_set) (nh2 : M S2 Empty_set).
Variables (emit1 : Z -> M S1 unit) (emit2 : Z -> M S2 unit).

Local Notation sizes := (map (@snd (P1 * P2) Z)).
Local Notation pairs := (map (@fst (P1 * P2) Z)).

(* [comment removed for export] *)
Definition Qm (X : list (P1 * P2 * Z)) (w : Z) (n : Z) (r1 : option P1) (r2 : option P2) : rel :=
  match r1, r2 with
  | Some p, Some q => fun s1 mo1 s2 mo2 => RX ((p, q, n) :: X) (w - 1) s1 mo1 s2 mo2 /\ n < 2^63
  | None, None => RX X (w - 1)
  | _, _ => fun _ _ _ _ => False
  end.

(* [comment removed for export] *)
Hypothesis Hm : forall X w n, 0 <= n <= REQMAX -> HISTOK (n :: sizes X) -> 1 <= w -> rsim (RX X w) (malloc1 n) (malloc2 n) (Qm X w n).
Hypothesis Hf : forall X w p q n, rsim (RX ((p, q, n) :: X) w) (free1 p) (free2 q) (fun _ _ => RX X w).
Hypothesis Hperm : forall X Y w s1 mo1 s2 mo2, Permutation X Y -> RX X w s1 mo1 s2 mo2 -> RX Y w s1 mo1 s2 mo2.
Hypothesis Hw : forall X w w' s1 mo1 s2 mo2, 0 <= w' <= w -> RX X w s1 mo1 s2 mo2 -> RX X w' s1 mo1 s2 mo2.
Hypothesis Hnh : forall X w (Q : Empty_set -> Empty_set -> rel), rsim (RX X w) nh1 nh2 Q.
Hypothesis Hemit : forall X w v, rsimeq (RX X w) (emit1 v) (emit2 v) (fun _ => RX X w).

Local Ltac ret_same := apply rsimeq_ret; intros ? ? ? ? HH; exact HH.
Local Ltac ret_rel := apply rsim_ret; intros ? ? ? ? HH.

