Section Driver.
Context {P1 P2 : Type}.
Variables (io1_ : IOStyle S1) (io2_ : IOStyle S2).
Variables (malloc1 : Z -> M S1 (option P1)) (malloc2 : Z -> M S2 (option P2)).
Variables (free1 : P1 -> M S1 unit) (free2 : P2 -> M S2 unit).
Variables (rs1 rs2 : Z).      (* [comment removed for export] *)
Variables (alloc_init1 : Z -> M S1 unit) (alloc_init2 : Z -> M S2 unit).
Variables (run1 : Z -> list Z -> M S1 Z) (run2 : Z -> list Z -> M S2 Z).
Variables (alloc_count1 : M S1 Z) (alloc_count2 : M S2 Z).
Variable RX : list (P1 * P2 * Z) -> Z -> rel.

Local Notation sizes := (map (@snd (P1 * P2) Z)).
Local Notation Qm := (Qm RX).
Hypothesis Hm : forall X w n, 0 <= n <= REQMAX -> HISTOK (n :: sizes X) -> 1 <= w -> rsim (RX X w) (malloc1 n) (malloc2 n) (Qm X w n).
Hypothesis Hf : forall X w p q n, rsim (RX ((p, q, n) :: X) w) (free1 p) (free2 q) (fun _ _ => RX X w).
Hypothesis Hperm : forall X Y w s1 mo1 s2 mo2, Permutation X Y -> RX X w s1 mo1 s2 mo2 -> RX Y w s1 mo1 s2 mo2.
Hypothesis Hw : forall X w w' s1 mo1 s2 mo2, 0 <= w' <= w -> RX X w s1 mo1 s2 mo2 -> RX X w' s1 mo1 s2 mo2.
Hypothesis Hdiag : forall X w d, diag_short d -> rsimeq (RX X w) (io_diag io1_ d) (io_diag io2_ d) (fun _ => RX X w).
Hypothesis Hinit : forall X w bm, rsimeq (RX X w) (alloc_init1 bm) (alloc_init2 bm) (fun _ => RX X w).
Hypothesis Hcount : forall X w, rsimeq (RX X w) alloc_count1 alloc_count2 (fun _ => RX X w).
(* [comment removed for export] *)
Hypothesis Hrun : forall X w cfg payload, (length X <= 1)%nat -> zlength payload <= MAX_INPUT -> RUN_OPS <= w ->
  rsimeq (RX X w) (run1 cfg payload) (run2 cfg payload) (fun _ => RX X (w - RUN_OPS)).
Hypothesis Hopen : forall X w path, rsimeq (RX X w) (msys (NOpen path) dec_open) (msys (NOpen path) dec_open) (fun _ => RX X w).
Hypothesis Hclose : forall X w fd, rsimeq (RX X w) (msys (NClose fd) dec_close) (msys (NClose fd) dec_close) (fun _ => RX X w).
Hypothesis Hread : forall X w fd buf1 buf2 cnt, 0 <= cnt < 2^64 ->
  rsimeq (RX X w) (msys (NRead fd buf1 cnt) (dec_read buf1 cnt)) (msys (NRead fd buf2 cnt) (dec_read buf2 cnt))
         (fun a => match a with RdData bs => fun s1 mo1 s2 mo2 => RX X w s1 mo1 s2 mo2 /\ zlength bs <= cnt | RdErr _ => RX X w end).

(* [comment removed for export] *)
Definition READ_OPS : Z := 11.
Definition MAIN_OPS : Z := READ_OPS + RUN_OPS.

(* [comment removed for export] *)
Definition rd_rel (wb : Z) (st1 : @rd_st P1) (st2 : @rd_st P2) : rel := fun s1 mo1 s2 mo2 =>
  exists w, RX [(rd_buf st1, rd_buf st2, rd_cap st1)] w s1 mo1 s2 mo2 /\ rd_cap st2 = rd_cap st1 /\ rd_content st2 = rd_content st1
  /\ zlength (rd_content st1) <= rd_cap st1 /\ (exists k, (k <= 10)%nat /\ rd_cap st1 = 65536 * 2 ^ Z.of_nat k /\ wb + (10 - Z.of_nat k) <= w) /\ 0 <= wb.

Definition QR (wb : Z) (r1 : @rd_result P1) (r2 : @rd_result P2) : rel :=
  match r1, r2 with
  | RdExit, RdExit => fun s1 mo1 s2 mo2 => exists X' w', RX X' w' s1 mo1 s2 mo2
  | RdDone b1 c1, RdDone b2 c2 => fun s1 mo1 s2 mo2 => (exists cap, RX [(b1, b2, cap)] wb s1 mo1 s2 mo2) /\ c2 = c1 /\ zlength c1 <= MAX_INPUT
  | _, _ => fun _ _ _ _ => False
  end.

