Lemma read_loop_body_sim : forall fd path wb st1 st2, zlength path <= PIECE_MAX ->
  rsim (rd_rel wb st1 st2) (read_loop_body io1_ malloc1 free1 rs1 fd path st1) (read_loop_body io2_ malloc2 free2 rs2 fd path st2)
       (fun r1 r2 => match r1, r2 with
                     | inl st1', inl st2' => rd_rel wb st1' st2'
                     | inr res1, inr res2 => QR wb res1 res2
                     | _, _ => fun _ _ _ _ => False
                     end).
